import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
a = list(map(int, data[1:]))

# Check if the input is valid
if len(a) != n - 1:
    print(-1)
    exit()

# Create a graph
graph = [[] for _ in range(n + 1)]
for i in range(n - 1):
    graph[a[i]].append(i + 1)

# Find the root (lamp connected to the power grid)
root = None
for i in range(1, n + 1):
    if len(graph[i]) == 1:
        root = i
        break

if root is None:
    print(-1)
    exit()

# Perform DFS to check if the graph is a tree
visited = [False] * (n + 1)
def dfs(node, parent):
    visited[node] = True
    for neighbor in graph[node]:
        if neighbor != parent:
            if visited[neighbor]:
                return False
            if not dfs(neighbor, node):
                return False
    return True

if not dfs(root, -1):
    print(-1)
    exit()

# Find the parent of each node
parent = [-1] * (n + 1)
def find_parent(node, p):
    parent[node] = p
    for neighbor in graph[node]:
        if neighbor != p:
            find_parent(neighbor, node)

find_parent(root, -1)

# Generate the output
print(root)
for i in range(n - 1):
    if parent[a[i]] == i + 1:
        print(a[i], i + 1)
    else:
        print(i + 1, a[i])
